import{_ as e,o as s,c as n,a2 as i}from"./chunks/framework.D8Tso2Ul.js";const u=JSON.parse('{"title":"Firmas digitales y DS 44","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/firmas-digitales.md","filePath":"ds44/firmas-digitales.md"}'),t={name:"ds44/firmas-digitales.md"};function d(r,a,o,l,c,p){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="firmas-digitales-y-ds-44" tabindex="-1">Firmas digitales y DS 44 <a class="header-anchor" href="#firmas-digitales-y-ds-44" aria-label="Permalink to &quot;Firmas digitales y DS 44&quot;">​</a></h1><p>El DS 44 exige que los registros de SST estén <strong>firmados y disponibles</strong> ante fiscalización. Build &amp; Serve digitaliza la firma manteniendo una cadena de evidencia verificable para cada acto firmado.</p><div class="warning custom-block"><p class="custom-block-title">Consulta legal pendiente</p><p>La <strong>validez jurídica del PIN como firma electrónica</strong> ante un fiscalizador del DS 44 está siendo evaluada con la Dirección del Trabajo y el proveedor de firma certificada (acuerdo reunión CCHC 2026-06-10). La funcionalidad opera con normalidad, pero <strong>no debe usarse como única prueba legal</strong> hasta obtener respuesta oficial.</p><p>La implementación actual (<code>FirmaService</code>: PIN + token + IP + timestamp en <code>SignaturesTable</code>) <strong>no debe modificarse</strong> hasta entonces. Aplica a firmas de documentos, firma asistida, firma cruzada de relator (<code>CAPACITACION_SST</code>) y validación de entregas de EPP.</p></div><h2 id="estrategias-de-firma" tabindex="-1">Estrategias de firma <a class="header-anchor" href="#estrategias-de-firma" aria-label="Permalink to &quot;Estrategias de firma&quot;">​</a></h2><p><code>FirmaService</code> implementa un patrón de estrategia con cuatro métodos de validación (<code>metodoValidacion</code>):</p><table tabindex="0"><thead><tr><th>Estrategia</th><th>Código</th><th>Uso</th></tr></thead><tbody><tr><td>PIN</td><td><code>PIN</code></td><td>Firma estándar con PIN personal de la persona</td></tr><tr><td>Offline</td><td><code>OFFLINE</code></td><td>Firma en terreno sin conexión, sincronizada después</td></tr><tr><td>Presencial</td><td><code>PRESENCIAL</code></td><td>Firma asistida ante un relator o supervisor presente</td></tr><tr><td>Biométrica</td><td><code>BIOMETRIC</code></td><td>Reservada (stub) — no implementada aún</td></tr></tbody></table><h2 id="registro-inmutable" tabindex="-1">Registro inmutable <a class="header-anchor" href="#registro-inmutable" aria-label="Permalink to &quot;Registro inmutable&quot;">​</a></h2><p>Cada firma genera un registro en <code>SignaturesTable</code> que <strong>no se modifica ni elimina</strong>. Los campos clave de evidencia son:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>signatureId      Identificador único de la firma</span></span>
<span class="line"><span>personaId        Quién firmó</span></span>
<span class="line"><span>personaRut       RUT del firmante</span></span>
<span class="line"><span>tipoFirma        trabajador | relator | supervisor</span></span>
<span class="line"><span>referenciaId     Documento o actividad firmada</span></span>
<span class="line"><span>referenciaTipo   Tipo de la referencia</span></span>
<span class="line"><span>fecha / horario / timestamp   Marca temporal</span></span>
<span class="line"><span>ipAddress        IP desde la que se firmó</span></span>
<span class="line"><span>metodoValidacion PIN | OFFLINE | PRESENCIAL | BIOMETRIC</span></span>
<span class="line"><span>estado           valida | disputada | anulada</span></span></code></pre></div><p>Esta tríada <strong>PIN + IP + timestamp</strong> constituye la evidencia mínima que la plataforma conserva por cada firma.</p><h2 id="firma-offline-en-terreno" tabindex="-1">Firma offline en terreno <a class="header-anchor" href="#firma-offline-en-terreno" aria-label="Permalink to &quot;Firma offline en terreno&quot;">​</a></h2><p>Las obras suelen tener conectividad limitada. El flujo offline garantiza que la firma se capture igual y se sincronice al recuperar la red:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. La persona firma en tablet/móvil sin conexión</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>2. La firma se guarda cifrada (AES) en IndexedDB (cola local)</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>3. Al recuperar conexión, se sincroniza por lotes con reintentos exponenciales</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>4. Resolución de conflictos por timestamp del servidor</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>5. Registro definitivo en SignaturesTable</span></span></code></pre></div><p>Detalles operativos del módulo en <a href="/manual/modulos/firmas.html">Firmas Digitales</a>.</p><h2 id="tipos-de-firma-segun-el-documento" tabindex="-1">Tipos de firma según el documento <a class="header-anchor" href="#tipos-de-firma-segun-el-documento" aria-label="Permalink to &quot;Tipos de firma según el documento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Contexto</th><th>Quién firma</th><th>Tipo</th></tr></thead><tbody><tr><td>Documento de obra (DS 44)</td><td>Prevencionista / Trabajador</td><td>Según documento</td></tr><tr><td>Entrega de EPP</td><td>Trabajador + Supervisor</td><td><code>trabajador</code>, <code>supervisor</code></td></tr><tr><td>Capacitación SST</td><td>Asistentes + Relator</td><td><code>trabajador</code>, <code>relator</code></td></tr><tr><td>Documento diario asignado</td><td>Persona asignada</td><td><code>trabajador</code></td></tr></tbody></table><h2 id="estados-de-una-firma" tabindex="-1">Estados de una firma <a class="header-anchor" href="#estados-de-una-firma" aria-label="Permalink to &quot;Estados de una firma&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valida ──▶ disputada (si se cuestiona su autenticidad)</span></span>
<span class="line"><span>       └─▶ anulada   (si se invalida formalmente)</span></span></code></pre></div><p>Una firma <code>valida</code> es la evidencia activa de cumplimiento. Los estados <code>disputada</code> y <code>anulada</code> permiten gestionar controversias sin borrar el registro original, preservando la trazabilidad exigida por el DS 44.</p>`,19)])])}const f=e(t,[["render",d]]);export{u as __pageData,f as default};
